<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Ustawienia · '.$space['name'];?>
<div class="page-head"><div><p class="eyebrow">Przestrzeń · <?=Html::e($space['space_key'])?></p><h1>Ustawienia Space</h1></div><a class="button secondary" href="<?=Html::e(Url::to('/spaces/'.$space['space_key'].'?overview=1'))?>">Wróć</a></div>
<?php if(isset($_GET['saved'])):?><div class="alert success">Ustawienia zapisano.</div><?php elseif(isset($_GET['error'])):?><div class="alert danger">Nie udało się zapisać ustawień.</div><?php endif;?>
<section class="card section-card"><form method="post" class="grid compact-form"><?=Csrf::field()?><label>Nazwa<input name="name" value="<?=Html::e($space['name'])?>" maxlength="190" required></label><label>Widoczność<select name="visibility"><option value="logged_in" <?=$space['visibility']==='logged_in'?'selected':''?>>Wszyscy zalogowani</option><option value="private" <?=$space['visibility']==='private'?'selected':''?>>Prywatny</option><option value="restricted" <?=$space['visibility']==='restricted'?'selected':''?>>Według ACL</option></select></label><label class="span-all">Opis<textarea name="description" rows="4"><?=Html::e($space['description']??'')?></textarea></label><label>Strona startowa<select name="homepage_page_id"><option value="0">Przegląd Space</option><?php foreach($pagesList as $p):?><option value="<?=Html::e($p['id'])?>" <?=(int)($space['homepage_page_id']??0)===(int)$p['id']?'selected':''?>><?=Html::e($p['title'])?></option><?php endforeach;?></select></label><label class="span-all">Skróty sidebar JSON<textarea name="sidebar_json" rows="6" placeholder='[{"label":"Repozytorium","url":"https://example.org"}]'><?=Html::e($space['sidebar_config_json']??'')?></textarea><small>Maks. 20 linków. Dozwolone są ścieżki wewnętrzne oraz http/https.</small></label><div class="form-action"><button class="button">Zapisz</button></div></form></section>
<section class="card section-card"><h2>Archiwizacja</h2><p class="muted">Zarchiwizowany Space pozostaje dostępny do odczytu, ale nie można tworzyć w nim nowych stron.</p><form method="post" action="<?=Html::e(Url::to('/spaces/'.$space['space_key'].'/archive'))?>" onsubmit="return confirm('Zmienić stan archiwizacji tej przestrzeni?')"><?=Csrf::field()?><input type="hidden" name="archive" value="<?=$space['archived_at']?'0':'1'?>"><button class="button secondary"><?=$space['archived_at']?'Przywróć Space':'Archiwizuj Space'?></button></form></section>
